// The helper's skills (Muse overhaul, part 2, step A): src/skills/<slug>/SKILL.md (+ references/**/*.md, scripts/**), bundled as text
// through bundle.js (generated by build.mjs; see README.md). The static core lists every skill, one line each (SKILLS_INDEX, sorted by
// slug, byte-identical for everyone), with the rule to read the matching skill before doing that kind of task. read_skill({ slug, ref? })
// returns a SKILL.md or one of its references. No computer start; read-only; offered in every channel and to background helpers.
// - Frontmatter: name (= the folder), description (one line, "Use when…"), always (true|false). always: true skills are still only
//   listed, never inlined, so the prompt stays lean.
// - Same {{#flag}}…{{/flag}} switches as the docs (the Resident passes docFlags()); "TODO(Captain)" lines are never served.
// - Scripts are installed on the channel computer at /opt/1hc/skills/<slug>/scripts/ (scripts.js, ChannelComputer.installSkills).
// - Channel skills (later, skill-creator): pass them as opts.extra (same shape as SKILLS entries). They're listed after the built-ins
//   by read_skill and belong in the per-channel block, never in the static core. A built-in slug wins on a clash.
import { FILES } from "./bundle.js";
import { SKILLS_DIR } from "./scripts.js";
import { docText } from "../docs/index.js";

export const SLUG_RE = /^[a-z0-9]+(?:-[a-z0-9]+)*$/;

// "---\nkey: value\n…\n---\nbody" → { meta, body, error }. Values: true/false, a quoted or bare one-line string.
export function parseSkill(md) {
  const m = String(md).replace(/\r/g, "").match(/^---\n([\s\S]*?)\n---\n?([\s\S]*)$/);
  if (!m) return { meta: {}, body: String(md), error: "no frontmatter" };
  const meta = {};
  for (const line of m[1].split("\n")) {
    if (!line.trim()) continue;
    const kv = line.match(/^([a-z_]+):\s*(.*)$/); if (!kv) return { meta, body: m[2], error: `bad frontmatter line: ${line}` };
    let v = kv[2].trim();
    if (/^".*"$/.test(v) || /^'.*'$/.test(v)) v = v.slice(1, -1); else if (v === "true") v = true; else if (v === "false") v = false;
    meta[kv[1]] = v;
  }
  return { meta, body: m[2].replace(/^\n+/, ""), error: null };
}
// Problems with one skill's frontmatter (empty list = valid). Checked by the tests for every bundled skill.
export function skillProblems(slug, meta) {
  const p = [];
  if (!SLUG_RE.test(slug)) p.push(`slug "${slug}" must be lowercase letters, digits and hyphens`);
  if (meta.name !== slug) p.push(`name "${meta.name}" must equal the folder "${slug}"`);
  if (typeof meta.description !== "string" || !/^Use when /.test(meta.description)) p.push(`description must start with "Use when "`);
  else if (meta.description.length > 300 || /\{\{|\n/.test(meta.description)) p.push("description must be one plain line under 300 chars");
  if (typeof meta.always !== "boolean") p.push("always must be true or false");
  for (const k of Object.keys(meta)) if (!["name", "description", "always"].includes(k)) p.push(`unknown frontmatter key ${k}`);
  return p;
}

// Built-in skills, sorted by slug: { slug, description, always, body, refs: { name: md }, scripts: ["/opt/1hc/skills/<slug>/scripts/…"] }.
export const SKILLS = [...new Set(Object.keys(FILES).map((p) => p.split("/")[0]))].sort().map((slug) => {
  const { meta, body } = parseSkill(FILES[`${slug}/SKILL.md`]);
  const refs = {}, scripts = [];
  for (const p of Object.keys(FILES).sort()) {
    if (p.startsWith(`${slug}/references/`)) refs[p.slice(`${slug}/references/`.length).replace(/\.md$/, "")] = FILES[p];
    else if (p.startsWith(`${slug}/scripts/`)) scripts.push(`${SKILLS_DIR}/${p}`);
  }
  return { slug, description: String(meta.description ?? ""), always: meta.always === true, body, refs, scripts };
});
export const SKILL_SLUGS = SKILLS.map((s) => s.slug);
// The skills list for the static core: one line per skill, sorted. Byte-identical for everyone.
export const SKILLS_INDEX = SKILLS.map((s) => `- ${s.slug}: ${s.description}`).join("\n");
const EE_SKILLS = new Set(["gmail", "google-calendar", "google-drive"]);
export const coreSkillsIndex = SKILLS.filter((s) => !EE_SKILLS.has(s.slug)).map((s) => `- ${s.slug}: ${s.description}`).join("\n");

// "Self_Awareness", " skills/self-awareness/SKILL.md " → "self-awareness".
export const skillKey = (s) => String(s ?? "").trim().toLowerCase().replace(/\/?skill\.md$/, "").replace(/^(?:\/?opt\/1hc\/)?(?:src\/)?skills\//, "").replace(/\/.*$/, "").replace(/[\s_]+/g, "-");
const refKey = (s) => String(s ?? "").trim().replace(/^.*?references\//, "").replace(/\.md$/i, "").toLowerCase();
const all = (extra = []) => [...SKILLS, ...extra.filter((x) => x && SLUG_RE.test(x.slug) && !SKILL_SLUGS.includes(x.slug))];
export function findSkill(slug, extra = []) { const k = skillKey(slug); return all(extra).find((s) => s.slug === k) || null; }
// A reference by its name ("pdf/visual"), its file name ("references/pdf/visual.md"), or its last part when that's unique ("visual").
export function findRef(skill, ref) {
  const k = refKey(ref), names = Object.keys(skill.refs || {});
  const hit = names.find((n) => n.toLowerCase() === k) || (() => { const m = names.filter((n) => n.toLowerCase().split("/").pop() === k); return m.length === 1 ? m[0] : null; })();
  return hit ? { name: hit, md: skill.refs[hit] } : null;
}

export const READ_SKILL_TOOL = { type: "function", function: { name: "read_skill",
  description: "Read one of your skills: a step-by-step playbook for a kind of task, with its rules, scripts and the checks to pass before you hand anything over. Before you do a task a skill covers, read it and follow it. Pass ref to read one of its references. Fast, read-only, no computer needed. An unknown name returns the list.",
  parameters: { type: "object", properties: {
    slug: { type: "string", description: `The skill's name, one of: ${SKILL_SLUGS.join(", ")}` },
    ref: { type: "string", description: "Optional: the name of one of the skill's references, as the skill lists them" } }, required: ["slug"] } } };

const line = (s) => `- ${s.slug}: ${s.description}`;
export function skillsListText(extra = [], ee = true) {
  const own = all(extra).filter((s) => !SKILL_SLUGS.includes(s.slug));
  return `Skills you can read (pass the name to read_skill):\n${ee ? SKILLS_INDEX : coreSkillsIndex}${own.length ? `\nThis channel's own skills:\n${own.map(line).join("\n")}` : ""}`;
}
const refsLine = (s) => { const n = Object.keys(s.refs || {}); return n.length ? `References (read_skill with slug "${s.slug}" and ref): ${n.join(", ")}` : ""; };
// read_skill({ slug, ref }) → the skill's text (or one reference), or the list of skills / references. flags: the Resident's docFlags().
export function readSkill(a = {}, flags = {}, { extra = [] } = {}) {
  const ee = flags.ee !== false, found = findSkill(a?.slug, extra), s = !ee && EE_SKILLS.has(found?.slug) ? null : found, asked = String(a?.slug ?? "").trim().slice(0, 80);
  if (!s) return `${asked ? `There's no skill called "${asked}". ` : ""}${skillsListText(extra, ee)}`;
  if (String(a?.ref ?? "").trim()) {
    const r = findRef(s, a.ref);
    if (!r) return `The ${s.slug} skill has no reference called "${String(a.ref).trim().slice(0, 80)}". ${refsLine(s) || "It has no references."}`;
    return `[1Helm skill: ${s.slug}, reference: ${r.name}]\n${docText(r.md, flags)}`;
  }
  // design_mcp.py stays installed but is not listed: the design tools in the tool list are the way to reach the design sources.
  const listed = s.scripts.filter((p) => !p.endsWith("/design_mcp.py"));
  const tail = [refsLine(s), listed.length ? `Scripts on your computer: ${listed.join(", ")}` : ""].filter(Boolean).join("\n");
  return `[1Helm skill: ${s.slug}]\n${docText(s.body, flags)}${tail ? `\n\n${tail}` : ""}`;
}
